"""RICO investigation network model: relationships stay distinct from legal conclusions.

Scope rule: Any question may enter. No unsupported factual edge may be promoted.
Data is descriptive; a path, common company, or contract is never a guilt score.
"""
from collections import deque
from datetime import date
import hashlib
import json

STATUSES = {'documented', 'source_report', 'alleged', 'inferred', 'unverified', 'disputed', 'contradicted'}
AMOUNT_KINDS = {'minimum_commitment', 'up_to_contract', 'projected_conditional', 'finance_lease', 'credit_potential', 'donation', 'loan_principal', 'equity_option', 'reported_paid'}

class EvidenceNetwork:
    def __init__(self):
        self.nodes = {}
        self.edges = []
        self.sources = {}
        self.claims = {}
        self._edge_keys = set()

    def source(self, identifier, title, uri, scope, source_date=None, **kwargs):
        if scope not in ('public','private'): raise ValueError('invalid source scope')
        if identifier in self.sources: raise ValueError('source collision')
        self.sources[identifier] = {'id':identifier,'title':title,'uri':uri,'scope':scope,
                                    'source_date':source_date,**kwargs}
        return identifier

    def node(self, identifier, label, kind, **kwargs):
        if identifier in self.nodes:
            old=self.nodes[identifier]
            if old['label']!=label or old['kind']!=kind: raise ValueError('node identity collision')
            return identifier
        self.nodes[identifier] = {'id':identifier,'label':label,'kind':kind,**kwargs}
        return identifier

    def edge(self, source, target, relation, status, sources=None, date=None, *,
             valid_from=None, valid_to=None, scope='public', amount=None, note='', edge_group=None,
             evidence_class=None, **kwargs):
        if source not in self.nodes or target not in self.nodes: raise ValueError('unknown endpoint')
        if status not in STATUSES: raise ValueError('invalid epistemic status')
        if scope not in ('public','private'): raise ValueError('invalid scope')
        if status == 'documented' and not sources: raise ValueError('documented edge requires evidence')
        for r in sources or []:
            if not isinstance(r,dict) or r.get('id') not in self.sources: raise ValueError('unregistered evidence')
            if not str(r.get('locator','')).strip(): raise ValueError('source locator required')
            if scope == 'public' and self.sources[r['id']]['scope'] == 'private':
                raise ValueError('private evidence cannot substantiate public edge')
        if valid_from and valid_to and valid_from > valid_to: raise ValueError('inverted time interval')
        for value in (date,valid_from,valid_to):
            if value:
                try: date_obj = __import__('datetime').date.fromisoformat(value)
                except (ValueError,TypeError): raise ValueError('invalid date')
        if amount:
            if amount.get('kind') not in AMOUNT_KINDS: raise ValueError('amount kind unsupported')
            if amount.get('currency') != 'USD' or not isinstance(amount.get('usd_billion'),(int,float)) or amount.get('usd_billion')<0: raise ValueError('invalid amount')
        if date and valid_from and date < valid_from: pass # event and validity can differ
        srcs=sorted((r['id'],r.get('locator','')) for r in sources or [])
        core=(source,target,relation,status,date,valid_from,valid_to,scope,json.dumps(srcs))
        if core in self._edge_keys: return None
        self._edge_keys.add(core)
        payload={'id':'e'+hashlib.sha256(repr(core).encode()).hexdigest()[:14],
                 'source':source,'target':target,'relation':relation,'status':status,
                 'sources':sources or [],'date':date,'valid_from':valid_from,'valid_to':valid_to,
                 'scope':scope,'note':note,'evidence_class':evidence_class,
                 'edge_group':edge_group,'amount':amount,**kwargs}
        self.edges.append(payload)
        return payload['id']

    def claim(self, identifier, title, status, sources, *, contradicts=None, scope='public',
              missing=None, test=None, **kwargs):
        if status not in STATUSES: raise ValueError('invalid claim status')
        if identifier in self.claims: raise ValueError('claim collision')
        if any(s not in self.sources for s in sources): raise ValueError('unknown claim source')
        if scope=='public' and any(self.sources[s]['scope']=='private' for s in sources):
            raise ValueError('private claim source leaks')
        self.claims[identifier]={'id':identifier,'title':title,'status':status,'sources':sources,
                                 'contradicts':contradicts or [], 'scope':scope,
                                 'missing':missing or [],'test':test or '',**kwargs}
        return identifier

    def project(self, statuses={'documented'},scope='public', at=None):
        permitted = [e for e in self.edges if e['status'] in statuses and (e['scope']=='public' or scope=='private')]
        if at: permitted=[e for e in permitted if (not e['valid_from'] or e['valid_from']<=at) and (not e['valid_to'] or at<=e['valid_to'])]
        allowed_nodes={e['source'] for e in permitted}|{e['target'] for e in permitted}
        return {'nodes':[n for n in self.nodes.values() if n['id'] in allowed_nodes], 'edges':permitted}

    def path(self,a,b,statuses={'documented'},max_hops=7,scope='public'):
        g=self.project(statuses,scope)
        adjacency={}
        for e in g['edges']:
            adjacency.setdefault(e['source'],set()).add(e['target'])
            adjacency.setdefault(e['target'],set()).add(e['source'])
        q=deque([(a,[a])])
        while q:
            here,p=q.popleft()
            if here==b:return p
            if len(p)>max_hops:continue
            for nxt in sorted(adjacency.get(here,())):
                if nxt not in p:q.append((nxt,p+[nxt]))
        return []

    def overlap(self,p1,p2,relation='participates'):
        def company_ids(p): return {e['source'] for e in self.edges if e['target']==p and e['relation']==relation and e['status']=='documented'}
        return sorted(company_ids(p1)&company_ids(p2))

    def report(self):
        return {'nodes':len(self.nodes),'edges':len(self.edges),'sources':len(self.sources),
                'claims':len(self.claims), 'status_counts':{s:sum(e['status']==s for e in self.edges) for s in sorted(STATUSES)},
                'source_families':sorted({s.get('family',s['id']) for s in self.sources.values()})}

    def export(self):
        return {'schema':'GMRI/RICO-EVIDENCE-NETWORK/1.0','as_of':'2026-10-30',
                'limitations':'Graph topology and event co-occurrence do not prove criminal liability or causation.',
                'nodes':list(self.nodes.values()), 'edges':self.edges,
                'claims':list(self.claims.values()), 'sources':list(self.sources.values()),
                'summary':self.report()}
